fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    // Problem guarantees non-empty compatible inputs (same length or one of them length 1).
    assert!(m > 0 && n > 0, "Inputs must be non-empty");
    
    if m == n {
        // Same length: just return them as-is (we own a and b, so no extra clone)
        (a, b)
    } else if m == 1 {
        // a is a singleton: repeat its sole element to match b.len()
        let v = a[0];
        (vec![v; n], b)
    } else if n == 1 {
        // b is a singleton: repeat its sole element to match a.len()
        let v = b[0];
        (a, vec![v; m])
    } else {
        // According to the problem statement this cannot happen.
        panic!(
            "Incompatible lengths for broadcasting: {} and {}",
            m, n
        );
    }
}

fn main() {
    // Quick smoke tests:
    assert_eq!(
        broadcast_arrays(vec![5], vec![1, 2, 3]),
        (vec![5, 5, 5], vec![1, 2, 3])
    );
    assert_eq!(
        broadcast_arrays(vec![1, 2, 3], vec![7]),
        (vec![1, 2, 3], vec![7, 7, 7])
    );
    assert_eq!(
        broadcast_arrays(vec![9, 8], vec![3, 4]),
        (vec![9, 8], vec![3, 4])
    );
    println!("All tests passed!");
}